from format_lecon import paras
from medicaments_surface import source,zone,extrait
def cornee(l):
 s=source(51898)
 body=paras('Ciloxan collyre, n° Swissmedic 51898, contient de la ciprofloxacine 3 mg/ml. L’indication suisse couvre notamment l’ulcère cornéen bactérien à germe sensible. Le schéma suivant appartient au collyre et ne doit pas être transféré à la pommade.', 'Schéma exact AIPS pour ulcère cornéen, adultes et enfants dès un an :')+zone(s,'\nUlcère cornéen\n','\nConjonctivite ou blépharite bactérienne')+paras('Ces instillations intensives, y compris nocturnes, nécessitent organisation et surveillance spécialisées. L’ophtalmologue adapte la stratégie à la gravité, à la culture et à la résistance ; cette fiche ne fait pas de la ciprofloxacine une réponse universelle à toute kératite.', 'Enfant, citation AIPS :')+zone(s,'\nEnfants et adolescents\n','\nContre-indications')+paras('L’usage avant un an n’est pas établi par cette posologie ; ne pas extrapoler. Contre-indications, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Ne pas utiliser comme traitement d’une infection des structures oculaires profondes. Rechercher une réaction allergique et une surinfection ; une prolongation favorise des résistances.', 'Règle d’arrêt, citation AIPS :')+extrait(s,"Comme on ne peut pas exclure l'apparition de réactions allergiques, il faut arrêter tout traitement avec le collyre, solution ou la pommade Ciloxan lorsqu'on observe les premiers symptômes de rougeurs de la peau ou d'autres symptômes d'une hypersensibilité.")+paras('La fiche demande également l’arrêt au premier signe de tendinite. Ne pas porter de lentilles pendant l’infection et le traitement ; le délai de quinze minutes mentionné pour le conservateur ne constitue pas une permission de les remettre dans un œil infecté.', 'Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nEffet sur')+paras('Aucune étude spécifique d’interaction du collyre n’est rapportée. Examiner les traitements systémiques concomitants, notamment quinolones, anticoagulants et autres médicaments concernés par leur propre information professionnelle.', 'Une vision trouble nécessite d’éviter conduite et machines jusqu’au retour à une vision compatible. Des dépôts blancs sous traitement peuvent être médicamenteux ; seul le suivi clinique permet de les distinguer d’une aggravation de l’infection.')
 a=l.subwindow('ciloxan','Ciloxan collyre : ulcère bactérien',body,(35,))
 s=source(67710)
 body=paras('Virgan est un gel ophtalmique de ganciclovir 1,5 mg/g, n° Swissmedic 67710. Il est indiqué dans les kératites aiguës superficielles dues à Herpes simplex, après diagnostic approprié.', 'Posologie et durée, citations AIPS :')+zone(s,'\nPosologie usuelle\n','\nEnfants et adolescents')+paras('La complète réépithélialisation est évaluée par le professionnel. Le traitement n’est pas simplement arrêté dès que la douleur diminue.', 'Enfant, citation AIPS :')+zone(s,'\nEnfants et adolescents\n','\nMode d\'administration')+paras('Contre-indications, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Ce gel ne traite pas une rétinite à cytomégalovirus. L’efficacité pour les autres kératoconjonctivites virales n’est pas démontrée et les patients immunodéprimés n’ont pas fait l’objet d’une étude spécifique.', 'Autres collyres, citation AIPS :')+zone(s,'\nInteractions\n','\nGrossesse, allaitement')+paras('Grossesse, allaitement et contraception, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nEffet sur')+paras('Les précautions contraceptives s’appliquent aussi à ce traitement local : six mois après le traitement pour les femmes en âge de procréer et trois mois pour les hommes, selon la fiche citée. Elles ne doivent pas être omises en raison de la voie ophtalmique.', 'Le gel contient du chlorure de benzalkonium et peut irriter la surface. Suspendre les lentilles dans le contexte de kératite. Réévaluer rapidement en cas d’aggravation, d’intolérance ou de guérison insuffisante, et ne pas prolonger au-delà du schéma sans avis spécialisé.', 'Éviter conduite et machines si la vision est trouble après instillation. Le tube se conserve quatre semaines après ouverture, sans que cette durée autorise quatre semaines de traitement.')
 b=l.subwindow('virgan','Virgan : kératite herpétique superficielle',body,(36,))
 return a+' '+b
